        on_hand[sku] = on_hand.get(sku, 0) + qty
        if rec['type'] == 'SHP':
            if day > last_ship.get(sku, -1): last_ship[sku] = day
    dead = []
    for sku, qty in on_hand.items():
        if qty > 0:
            ship_day = last_ship.get(sku, -1000000)
            if today - ship_day >= idle_days: dead.append(sku)
