from typing import Sequence, Tuple, Mapping, Dict

def allocate_backorders(
    orders: Sequence[Tuple[str, int, int, Mapping[str, int]]],
    available: Mapping[str, int]
) -> Dict[str, Dict[str, int]]:
    """
    Allocate available stock to open backorders by priority.
    Orders are processed in the sequence provided. 
    An order is allocated all of its lines in full or nothing at all.
