                can_fill = False
                break

        if can_fill:
            order_alloc = {}
            for item, qty in lines.items():
                stock[item] -= qty
                order_alloc[item] = qty
            allocations[order_id] = order_alloc
        else:
            # Even if not filled, the output must contain an entry for every order
            # with 0 for every line requested in that order.
            allocations[order_id] = {item: 0 for item in lines}

    return allocations
