from typing import Mapping, Dict

def abc_classify(values: Mapping[str, int], a_pct: int = 80, b_pct: int = 95) -> Dict[str, str]:
    """
    Classify SKUs into A/B/C classes by cumulative value share.

    SKUs are sorted by value in descending order. 
    Class A: Top SKUs whose cumulative value share is <= a_pct.
    Class B: Next SKUs whose cumulative value share is <= b_pct.
    Class C: Remaining SKUs.

    If total value is 0, all SKUs are classified as 'C'.
    Negative values should raise a ValueError.
    """
    if not values:
        return {}

    if any(v < 0 for v in values.values()):
        raise ValueError("Values cannot be negative")

    total_value = sum(values.values())
    if total_value == 0:
        return {sku: "C" for sku in values}

    # Sort SKUs by value descending, then alphabetically for stability
    sorted_skus = sorted(values.keys(), key=lambda k: (-values[k], k))

    result = {}
    cumulative_value = 0

    for sku in sorted_skus:
        val = values[sku]
        cumulative_value += val
        share = (cumulative_value / total_value) * 100

        if share <= a_pct:
            result[sku] = "A"
        elif share <= b_pct:
            result[sku] = "B"
        else:
            result[sku] = "C"

    return result
