        on_hand[sku] = on_hand.get(sku, 0) + qty

        if rec['type'] == 'SHP':
            if day > last_ship.get(sku, -1):
                last_ship[sku] = day
        elif rec['type'] == 'RCV':
            if sku not in first_rcv or day < first_rcv[sku]:
                first_rcv[sku] = day

    dead = []
    for sku, qty in on_hand.items():
        if qty > 0:
            if sku in last_ship:
                reference_day = last_ship[sku]
            elif sku in first_rcv:
                reference_day = first_rcv[sku]
            else:
                continue

            if today - reference_day >= idle_days:
                dead.append(sku)

    return sorted(dead)"}}}
