from typing import Dict, List, Sequence, Tuple
from stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    """
    Split an order into parcels that respect the carrier's weight limit.
    """
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")

    # Consolidate quantities by SKU and verify consistent weights
    sku_totals: Dict[str, int] = {}
    sku_weights: Dict[str, int] = {}
    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("qty and unit weight must be > 0")
        if weight > max_parcel_grams:
            raise ValueError("single unit weight cannot exceed max_parcel_grams")
        if sku in sku_weights and sku_weights[sku] != weight:
            raise ValueError(f"SKU {sku} has inconsistent unit weights")
        sku_weights[sku] = weight
        sku_totals[sku] = sku_totals.get(sku, 0) + qty

    # Create chunks that are as large as possible but fit in one parcel
    chunks: List[Tuple[str, int, int]] = [] # (sku, qty, total_weight)
    for sku, total_qty in sku_totals.items():
        unit_weight = sku_weights[sku]
        units_per_parcel = max_parcel_grams // unit_weight

        remaining_qty = total_qty
        while remaining_qty > 0:
            chunk_qty = min(remaining_qty, units_per_parcel)
            chunks.append((sku, chunk_qty, chunk_qty * unit_weight))
            remaining_qty -= chunk_qty

    # Prepare items for first_fit_decreasing: (id, weight)
    # We use the index as the ID to recover the SKU and qty later
    weighted_items = [(i, chunk[2]) for i, chunk in enumerate(chunks)]

    bins = first_fit_decreasing(weighted_items, max_parcel_grams)

    result: List[Dict[str, int]] = []
    for bin_indices in bins:
        parcel: Dict[str, int] = {}
        for idx, _ in bin_indices:
            sku, qty, _ = chunks[idx]
            parcel[sku] = parcel.get(sku, 0) + qty
        result.append(parcel)

    return result"
    }
  }
}
