from typing import Sequence, Tuple, Mapping, Dict

def allocate_backorders(
    orders: Sequence[Tuple[str, int, int, Mapping[str, int]]],
    available: Mapping[str, int]
) -> Dict[str, Dict[str, int]]:
    """
    Allocate available stock to open backorders by priority.
    Orders are processed sorted by priority (asc) and then order number (asc).
    An order is allocated all of its lines in full or nothing at all.
    """
    # Validation: Quantities must be > 0
    for _, _, _, lines in orders:
        for qty in lines.values():
            if qty <= 0:
                raise ValueError("Order quantities must be greater than zero")

    # Sort orders by priority (index 1) and order number (index 2)
    sorted_orders = sorted(orders, key=lambda x: (x[1], x[2]))

    stock = available.copy()
    allocations = {}

    for order_id, priority, order_num, lines in sorted_orders:
        can_fill = True
        for item, qty in lines.items():
            if stock.get(item, 0) < qty:
                can_fill = False
                break

        if can_fill:
            order_alloc = {}
            for item, qty in lines.items():
                stock[item] -= qty
                order_alloc[item] = qty
            allocations[order_id] = order_alloc
        else:
            allocations[order_id] = {item: 0 for item in lines}

    return allocations
"}}}
