from typing import Sequence, Tuple, List, Dict
from stockflow.first_fit_decreasing import first_fit_decreasing

def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    """
    Splits an order into parcels under the carrier weight limit using First-Fit Decreasing.

    Args:
        lines: A sequence of (item_id, quantity, weight_per_unit).
        max_parcel_grams: The maximum weight allowed per parcel.

    Returns:
        A list of dictionaries where each dictionary represents a parcel and maps item_id to quantity.

    Raises:
        ValueError: If any single item exceeds the max_parcel_grams.
    """
    # Flatten the lines into individual items (id, weight)
    items = []
    for item_id, quantity, weight in lines:
        for _ in range(quantity):
            items.append((item_id, weight))

    # Use the FFD algorithm to group items into bins
    bins = first_fit_decreasing(items, max_parcel_grams)

    # Convert bins of (id, weight) tuples into dictionaries of {id: quantity}
    parcels = []
    for bin in bins:
        parcel_dict = {}
        for item_id, _ in bin:
            parcel_dict[item_id] = parcel_dict.get(item_id, 0) + 1
        parcels.append(parcel_dict)

    return parcels
"
