from typing import Iterable, Mapping, Tuple, List
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location

def cycle_count_variance(
    lines: Iterable[str], 
    case_sizes: Mapping[str, int], 
    counts: Mapping[Tuple[str, str], int]
) -> List[Tuple[str, str, int]]:
    """
    Reports differences between a cycle count and system stock.
    """
    stock_data = {}
    for line in lines:
        parts = line.split(';')
        if len(parts) < 5: continue
        sku, loc, qty_str = parts[2], parts[3], parts[4]
        norm_sku = normalize_sku(sku)
        norm_loc = parse_location(loc).lower()
        qty_val = int(qty_str.split(' ')[0])
        if qty_str.split(' ')[1] == 'CS':
            qty_val *= case_sizes.get(sku, 1)
        key = (norm_sku, norm_loc)
        if key not in stock_data:
            stock_data[key] = [sku, loc, 0]
        stock_data[key][2] += qty_val

    aggregated_counts = {}
    count_orig_keys = {}
    for (c_sku, c_loc), qty in counts.items():
        if qty < 0: raise ValueError("Count cannot be negative")
        n_sku = normalize_sku(c_sku)
        n_loc = parse_location(c_loc).lower()
        key = (n_sku, n_loc)
        aggregated_counts[key] = aggregated_counts.get(key, 0) + qty
        if key not in count_orig_keys:
            count_orig_keys[key] = (c_sku, c_loc)

    variances = []
    all_keys = sorted(set(stock_data.keys()) | set(aggregated_counts.keys()))
    for key in all_keys:
        sys_qty = stock_data[key][2] if key in stock_data else 0
        count_qty = aggregated_counts.get(key, 0)
        diff = count_qty - sys_qty
        if diff != 0:
            if key in stock_data:
                sku, loc = stock_data[key][0], stock_data[key][1]
            else:
                sku, loc = count_orig_keys[key]
            variances.append((sku, loc, diff))
    return variances
"}}}
